package export_ohrats_rc_plugin_package_source

import (
	"fmt"
	"strings"

	witTypes "go.bytecodealliance.org/pkg/wit/types"
	"wit_component/githubsource"
	"wit_component/ohrats_rc_plugin_package_source"
)

// Resolve selects a raw ".wasm" file when the spec names one, otherwise the
// component asset published by a GitHub release.
func Resolve(scheme string, value string) witTypes.Result[ohrats_rc_plugin_package_source.PackageArtifact, string] {
	if scheme != "github" {
		return witTypes.Err[ohrats_rc_plugin_package_source.PackageArtifact, string](
			fmt.Sprintf("GitHub source does not handle %q", scheme))
	}
	parsed, err := githubsource.Parse(value)
	if err != nil {
		return witTypes.Err[ohrats_rc_plugin_package_source.PackageArtifact, string](err.Error())
	}
	var artifact ohrats_rc_plugin_package_source.PackageArtifact
	if strings.HasSuffix(parsed.Path, ".wasm") {
		artifact, err = githubsource.RawComponent(parsed)
	} else {
		artifact, err = githubsource.ReleaseComponent(parsed)
	}
	if err != nil {
		return witTypes.Err[ohrats_rc_plugin_package_source.PackageArtifact, string](err.Error())
	}
	return witTypes.Ok[ohrats_rc_plugin_package_source.PackageArtifact, string](artifact)
}
